import React, { useState, useEffect } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test"; // ✅ Import Test Component

const App = () => {
  const [activePage, setActivePage] = useState("chat");

  // 🔹 Store chat messages globally so they don’t disappear when switching tabs
  const [messages, setMessages] = useState([]);

  // 🔹 Store previously discussed topics for the Test feature
  const [previousTopics, setPreviousTopics] = useState([]);

  // 🔹 Store last searched query (for YouTube & Wikipedia)
  const [latestQuery, setLatestQuery] = useState("");

  // ✅ Load chat messages and topics from localStorage (Optional: To persist after refresh)
  useEffect(() => {
    const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
    const savedTopics = JSON.parse(localStorage.getItem("previousTopics")) || [];

    setMessages(savedMessages);
    setPreviousTopics(savedTopics);
  }, []);

  // ✅ Save messages and topics whenever they change
  useEffect(() => {
    localStorage.setItem("messages", JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem("previousTopics", JSON.stringify(previousTopics));
  }, [previousTopics]);

  return (
    <div className="app-container">
      <Navbar setActivePage={setActivePage} />

      <div className="content">
        {activePage === "chat" && (
          <ChatBox
            messages={messages}
            setMessages={setMessages}
            setLatestQuery={setLatestQuery}
            setPreviousTopics={setPreviousTopics} // ✅ Pass previousTopics state
            previousTopics={previousTopics} // ✅ Send stored topics to ChatBox
          />
        )}
        {activePage === "youtube" && <YouTube latestQuery={latestQuery} />}
        {activePage === "wikipedia" && <Wikipedia latestQuery={latestQuery} />}
        {activePage === "test" && <Test previousTopics={previousTopics} />} {/* ✅ Add Test Page */}
      </div>

      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
